// Event-log parity vectors, generated by running the ORIGINAL PWA's REAL
// syncEventsPush / syncEventsPull / syncEventsDeleteDevice and the evt helpers at the
// pinned commit, in a vm sandbox with fakes (the same harness shape as that project's own
// tests/evtpush-shrink-guard.test.js and tests/evtpull-selfhealing.test.js).
//
// The PWA is a separate repository, https://github.com/Palo007/Questa, NOT vendored here.
// Read-only on it: the source text comes from `git show <rev>:sync.js`.
// Output: app/src/test/resources/events/evt_vectors.json (consumed by EvtOptiVectorsTest).
//
// Run: node tools/gen_evt_vectors.mjs [optiRoot]
import { execFileSync } from 'node:child_process';
import { writeFileSync, mkdirSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
import vm from 'node:vm';
import { webcrypto } from 'node:crypto';

const __dirname = dirname(fileURLToPath(import.meta.url));
const TARGET_OPTI_GIT = '7d5d4f3';
// $OPTI_ROOT, else a sibling checkout named `Opti`. Was a hardcoded absolute path under one
// maintainer's home directory, so it resolved for exactly one person on one machine.
const OPTI_ROOT = process.argv[2] || process.env.OPTI_ROOT || join(dirname(__dirname), 'Opti');
const NOW = Date.UTC(2026, 8, 24, 12, 0, 0); // 2026-09-24T12:00:00.000Z (manifest frozenNow)
const DAY = 86400000;
const AGE = 18 * 30 * DAY;
const MY_DEV = 'dev-me';
const CFG = 'questa.sync.v1';

let src = execFileSync('git', ['-C', OPTI_ROOT, 'show', TARGET_OPTI_GIT + ':sync.js'], { encoding: 'utf8', maxBuffer: 64 << 20 });
src = src.replace(/\/\* BEGIN_BOOT_GATE \*\/[\s\S]*?\/\* END_BOOT_GATE \*\//, '/* boot gate stripped */');

const RealDate = Date;
class FixedDate extends RealDate {
  constructor(...a){ if(a.length === 0) super(NOW); else super(...a); }
  static now(){ return NOW; }
}

function clone(x){ return JSON.parse(JSON.stringify(x)); }

function makeCtx(opts){
  opts = opts || {};
  const store = {};
  const noop = function(){};
  const calls = { list: 0, download: 0, upload: 0, del: 0 };
  const uploads = [];
  const deletes = [];
  const inserted = [];
  const diag = [];
  const records = clone(opts.records || []);
  const sandbox = {
    window: {}, navigator: { onLine: true },
    document: { addEventListener: noop, getElementById(){ return null; }, createElement(){ return { style: {}, appendChild: noop, setAttribute: noop, click: noop }; }, body: { appendChild: noop, removeChild: noop } },
    localStorage: {
      getItem(k){ return Object.prototype.hasOwnProperty.call(store, k) ? store[k] : null; },
      setItem(k, v){ store[k] = String(v); }, removeItem(k){ delete store[k]; }, key(){ return null; }, length: 0
    },
    history: { replaceState: noop },
    location: { search: '', origin: 'https://test.example', pathname: '/', href: '' },
    crypto: webcrypto,
    setTimeout(){ return 0; }, clearTimeout: noop, setInterval(){ return 0; }, clearInterval: noop,
    console, JSON, Math, Date: FixedDate, Map, Set, WeakSet, Array, Object, Number, String, Boolean, Promise, isNaN,
    URLSearchParams, TextEncoder, Buffer, Uint8Array, ArrayBuffer,
    fetch: null, logEvent: noop, toast: noop, render: noop, esc(x){ return x; }, save: noop,
    uid(){ return MY_DEV; },
    EVENTS_STORE: 'events'
  };
  sandbox.getEvents = function(o){
    o = o || {};
    if(o.strict && opts.strictFails) return Promise.resolve(null);
    const from = o.from != null ? o.from : -Infinity;
    const to = o.to != null ? o.to : Infinity;
    return Promise.resolve(clone(records.filter(e => e.ts >= from && e.ts <= to).sort((a, b) => a.ts - b.ts)));
  };
  sandbox.idbOpen = function(){
    return Promise.resolve({
      transaction(){
        const tx = {};
        const batch = [];
        tx.objectStore = function(){ return { add(r){ batch.push(clone(r)); } }; };
        Promise.resolve().then(function(){
          if(opts.idb === 'abort'){ if(tx.onabort) tx.onabort(); }
          else { batch.forEach(r => inserted.push(r)); if(tx.oncomplete) tx.oncomplete(); }
        });
        return tx;
      }
    });
  };
  sandbox.window.__qDiag = { errors: diag };
  sandbox._qDiagPush = function(kind, data){
    diag.push(Object.assign({ t: FixedDate.now(), kind }, data));
    if(diag.length > 50) diag.shift();
  };
  sandbox.window.addEventListener = noop;
  sandbox.self = sandbox.window; sandbox.globalThis = sandbox;
  sandbox.S = { char: { name: 'T', lvl: 1, updatedAt: 1000 }, tasks: [], rewards: [], tags: [], devices: [], an: { views: [], metrics: [] }, history: [], charHistory: [], monthlyBackups: [], lastCron: 0, deletions: [] };
  vm.createContext(sandbox);
  vm.runInContext(src, sandbox);
  store[CFG] = JSON.stringify(Object.assign({
    enabled: true, appKey: 'k', refreshToken: 'rt', accessToken: 'at', accessExpiresAt: NOW + 3600000,
    lastRev: null, lastSyncAt: null, lastError: null, deviceId: MY_DEV,
    evtLastUploadTs: 0, evtFileRevs: {}, evtLastPullAt: 0, evtFullScanAt: 0, evtBadRevs: {},
    evtFullPushAt: 0, evtFileCounts: {}, evtPushBlocked: {}
  }, opts.cfg || {}));
  sandbox.dbxListFolder = function(){ calls.list++; if(opts.listFails) return Promise.reject(new Error('list failed: 500')); return Promise.resolve(clone(opts.entries || [])); };
  sandbox.dbxDownloadRaw = function(p){
    calls.download++;
    const name = String(p).split('/').pop();
    return Promise.resolve(opts.downloads && Object.prototype.hasOwnProperty.call(opts.downloads, name) ? clone(opts.downloads[name]) : null);
  };
  sandbox.dbxUploadText = function(p, text){
    calls.upload++;
    if(opts.uploadFails) return Promise.reject(new Error('upload failed: 500'));
    uploads.push({ path: String(p), records: JSON.parse(text) });
    return Promise.resolve({ rev: 'r' });
  };
  sandbox.dbxDelete = function(p){
    calls.del++;
    deletes.push(String(p));
    if(opts.deleteFails && opts.deleteFails.includes(String(p))) return Promise.reject(new Error('delete failed'));
    return Promise.resolve();
  };
  return { sandbox, store, calls, uploads, deletes, inserted, diag };
}

const EVT_KEYS = ['evtLastUploadTs', 'evtFullPushAt', 'evtFileCounts', 'evtPushBlocked', 'evtFileRevs', 'evtBadRevs', 'evtLastPullAt', 'evtFullScanAt'];
function cfgOut(c){ const cfg = JSON.parse(c.store[CFG]); const o = {}; EVT_KEYS.forEach(k => { o[k] = cfg[k] === undefined ? null : cfg[k]; }); return o; }

async function runScenario(s){
  const c = makeCtx(s);
  let threw = null;
  try{
    if(s.op === 'push') await c.sandbox.window.QuestaSync.eventsPush(s.opts);
    else if(s.op === 'pull') await c.sandbox.window.QuestaSync.eventsPull(s.opts);
    else if(s.op === 'purge') await c.sandbox.window.QuestaSync.eventsDeleteDevice(s.devId);
  }catch(e){ threw = String((e && e.message) || e); }
  return Object.assign({}, s, {
    expect: { threw, cfg: cfgOut(c), uploads: c.uploads, deletes: c.deletes, inserted: c.inserted, diag: c.diag, calls: c.calls }
  });
}

// ---- scenario inputs --------------------------------------------------------------------
const H = makeCtx().sandbox.window.QuestaSync.evtHelpers;
const CUR = H.evtMonthKey(NOW);
const PREV = H.evtMonthKey(NOW - 40 * DAY);
const CUTOFF = NOW - AGE;
const STRADDLE = H.evtMonthKey(CUTOFF);
const SR = H.evtMonthRange(STRADDLE);
const OLD = H.evtMonthKey(CUTOFF - 60 * DAY);
const FUT = H.evtMonthKey(NOW + 400 * DAY);
