L('pull_corrupt_and_neighbour', { entries: [{ name: oName, rev: 'rbad' }, { name: fn('dev-o2', CUR), rev: 'rgood' }], downloads: { [oName]: { text: 'not json {', rev: 'rbad' }, [fn('dev-o2', CUR)]: { text: JSON.stringify([other('dev-o2', 'g-1', NOW - 100)]), rev: 'rgood' } } });
L('pull_not_array', { entries: [{ name: oName, rev: 'r1' }], downloads: { [oName]: { text: '{"a":1}', rev: 'r1' } } });
