L('pull_bad_rev_backoff', { cfg: { evtBadRevs: { [oName]: { rev: 'r1', at: NOW - 900000 + 1 } } }, entries: [{ name: oName, rev: 'r1' }], downloads: { [oName]: { text: JSON.stringify(oRecs), rev: 'r1' } } });
L('pull_bad_rev_retry_at_15min', { cfg: { evtBadRevs: { [oName]: { rev: 'r1', at: NOW - 900000 } } }, entries: [{ name: oName, rev: 'r1' }], downloads: { [oName]: { text: JSON.stringify(oRecs), rev: 'r1' } } });
L('pull_bad_rev_full_scan_ignores_backoff', { cfg: { evtFullScanAt: NOW - DAY - 1, evtBadRevs: { [oName]: { rev: 'r1', at: NOW - 1000 } } }, entries: [{ name: oName, rev: 'r1' }], downloads: { [oName]: { text: JSON.stringify(oRecs), rev: 'r1' } } });
