// ---- helper vectors -----------------------------------------------------------------------
async function helpers(){
  const out = { sig: [], disambiguate: [], uidHash: [], superset: [], filterSet: [], monthOlder: [] };
  const sigInputs = [
    { ts: 1, kind: 'a' }, { ts: 1.5, kind: 'a', taskId: 't', dir: -1, reps: 3 }, { ts: 2, kind: 'k', detail: 5, subId: 's', done: false },
    { ts: 2, kind: 'k', done: null }, { ts: 2, kind: 'k', done: 'yes' }, { ts: 1e21, kind: 'k', dir: 0, reps: 0 },
    { ts: 3, kind: 'k', detail: '', taskId: '' }, { ts: 3, kind: null, dir: '2' }, { ts: 3, kind: 'k', detail: true },
    { ts: 3, kind: 'k', detail: [1, 2] }, { ts: 3, kind: 'k', detail: { a: 1 } }, { ts: 3, kind: 'ž€😀', taskId: 'ü' }
  ];
  sigInputs.forEach(r => out.sig.push({ r, sig: H.evtIncomingSig(r) }));
  [['u', 'a|b'], ['rep-1', ''], ['x', 'ž€😀'], ['dev-1-abc', '1788220800000|habitTap||0|0|||']].forEach(([u, s]) => out.disambiguate.push({ uid: u, sig: s, out: H.evtUidDisambiguate(u, s) }));
  const hashInputs = [[], ['a'], ['b', 'a', 'c'], ['a', 'a'], ['Z', 'a', '_', 'ž', '😀'], [null, 'x', '']];
  for(const uids of hashInputs){ out.uidHash.push({ uids, hash: await H.uidHash(uids.map(u => ({ uid: u }))) }); }
  const h2 = await H.uidHash([{ uid: 'a' }, { uid: 'b' }]);
  out.superset.push({ local: ['a', 'b'], knownHash: 'x', knownUids: ['a'], localHash: h2, out: H.uidsAreSuperset([{ uid: 'a' }, { uid: 'b' }], 'x', ['a'], h2) });
  out.superset.push({ local: ['a'], knownHash: 'x', knownUids: ['a', 'b'], localHash: 'y', out: H.uidsAreSuperset([{ uid: 'a' }], 'x', ['a', 'b'], 'y') });
  out.superset.push({ local: ['a', 'b'], knownHash: h2, knownUids: [], localHash: h2, out: H.uidsAreSuperset([{ uid: 'a' }, { uid: 'b' }], h2, [], h2) });
  out.superset.push({ local: ['a', 'b'], knownHash: h2, knownUids: null, localHash: null, out: H.uidsAreSuperset([{ uid: 'a' }, { uid: 'b' }], h2, null, undefined) });
  out.superset.push({ local: ['a'], knownHash: 'fallback-1', knownUids: null, localHash: 'fallback-1', out: H.uidsAreSuperset([{ uid: 'a' }], 'fallback-1', null, 'fallback-1') });
  out.superset.push({ local: ['a'], knownHash: null, knownUids: null, localHash: 'q', out: H.uidsAreSuperset([{ uid: 'a' }], undefined, undefined, 'q') });
  // legacy Set form (G5's call shape)
  const recs = [other('d', 'u1', NOW - 1), other('d', 'u1', NOW - 2), other('d', 'u2', NOW - 3)];
  out.filterSet.push({ records: recs, existing: ['u2'], out: H.evtIncomingFilter(recs, new Set(['u2']), MY_DEV, NOW, AGE) });
  [[CUR, NOW], [OLD, NOW], [STRADDLE, NOW]].forEach(([m, n]) => out.monthOlder.push({ month: m, now: n, out: H.evtMonthOlderThan(m, n, AGE) }));
  return out;
}

const result = { opti: TARGET_OPTI_GIT, now: NOW, myDev: MY_DEV, ageLimitMs: AGE, helpers: await helpers(), scenarios: [] };
for(const s of scenarios) result.scenarios.push(await runScenario(s));
const outDir = join(__dirname, '..', 'app', 'src', 'test', 'resources', 'events');
mkdirSync(outDir, { recursive: true });
writeFileSync(join(outDir, 'evt_vectors.json'), JSON.stringify(result, null, 1) + '\n');
console.log('gen_evt_vectors: ' + result.scenarios.length + ' scenarios -> ' + join(outDir, 'evt_vectors.json'));
